def strategy(agent_id, my_history, observations, round_num, recipient_id, population_size):
    # Variant: base decision on a sliding window of recent rounds
    window_size = 3
    recent = my_history[-window_size:] if len(my_history) >= window_size else my_history
    recent_donations = sum(1 for action in recent if action)
    # Donate if fewer than half of recent rounds were donations
    if recent_donations < len(recent) / 2:
        return True
    else:
        return False

def strategy(agent_id, my_history, observations, round_num, recipient_id, population_size):
    # Count donations made in past rounds
    donations_made = sum(1 for action in my_history if action)
    past_rounds = len(my_history)
    # Donate only if we have been more reluctant than 40% of past rounds
    if donations_made < past_rounds * 0.4:
        return True
    else:
        return False

